const triggerData = $('Execute Workflow Trigger').first().json || {};
const queryObj = triggerData.query || {};

// 1. Resilient parameter extraction
const action = (triggerData.action || queryObj.action || 'list').toLowerCase().trim();
const sheetId = triggerData.sheetId || queryObj.sheetId || '';
const categoryInput = (triggerData.category || queryObj.category || triggerData.name || queryObj.name || '').trim();
const monthlyLimitRaw = triggerData.monthlyLimit !== undefined ? triggerData.monthlyLimit : (queryObj.monthlyLimit !== undefined ? queryObj.monthlyLimit : (triggerData.limit || queryObj.limit || triggerData.amount || queryObj.amount));
const monthlyLimit = monthlyLimitRaw !== undefined && monthlyLimitRaw !== null ? parseFloat(monthlyLimitRaw) : null;
const notesInput = triggerData.notes || queryObj.notes || '';

const currentMonthStr = new Date().toISOString().substring(0, 7); // e.g. "2026-10"

// 2. Fetch Budgets rows safely
let budgetRows = [];
try {
  budgetRows = $('Read Budgets Sheet').all().map(r => r.json).filter(b => b && b.category);
} catch(e) {}

const firstBudgetItem = $('Read Budgets Sheet').first()?.json || {};
if (firstBudgetItem.error) {
  return [{
    json: {
      operationType: 'read_only',
      success: false,
      status: 'SHEET_TAB_NOT_FOUND',
      response: "⚠️ The 'Budgets' tab was not found in your Google Sheet. Please add a tab named 'Budgets' with columns: category, monthlyLimit, currentSpent, remaining, lastAlertLevel, month, updatedAt.",
      error: firstBudgetItem.error
    }
  }];
}

// 3. Fetch Transactions rows and calculate actual ledger spending for current month
let txRows = [];
try {
  txRows = $('Read Transactions Sheet').all().map(r => r.json).filter(t => t && t.amount !== undefined && t.type !== 'Deleted');
} catch(e) {}

const categorySpendMap = {};
for (const tx of txRows) {
  const txDate = tx.date || '';
  if (!txDate.startsWith(currentMonthStr)) continue; // Only current month transactions

  const amt = parseFloat(tx.amount) || 0;
  const type = (tx.type || 'expense').toLowerCase();
  const cat = (tx.category || 'Other').trim();

  if (type === 'income') continue; // Exclude income

  categorySpendMap[cat] = (categorySpendMap[cat] || 0) + amt;
}

// Normalize category matcher
function findMatchingBudget(catName) {
  if (!catName) return null;
  const clean = catName.toLowerCase().replace(/[^a-z0-9]/g, '');
  return budgetRows.find(b => {
    const bClean = (b.category || '').toLowerCase().replace(/[^a-z0-9]/g, '');
    return bClean === clean || bClean.includes(clean) || clean.includes(bClean);
  });
}

// 4. Dispatch Actions

// ACTION: SET / CREATE / UPDATE BUDGET
if (action === 'set' || action === 'create' || action === 'update') {
  if (!categoryInput) {
    return [{
      json: {
        operationType: 'read_only',
        success: false,
        status: 'MISSING_CATEGORY',
        response: '⚠️ Please specify a category for the budget (e.g., Food & Dining, Shopping, Travel).'
      }
    }];
  }
  if (!monthlyLimit || monthlyLimit <= 0) {
    return [{
      json: {
        operationType: 'read_only',
        success: false,
        status: 'INVALID_LIMIT',
        response: '⚠️ Please specify a valid monthly spending limit greater than 0.'
      }
    }];
  }

  const existing = findMatchingBudget(categoryInput);
  const currentSpent = categorySpendMap[categoryInput] || (existing ? (categorySpendMap[existing.category] || 0) : 0);
  const remaining = Math.max(0, monthlyLimit - currentSpent);
  const percentage = Math.round((currentSpent / monthlyLimit) * 100);
  const nowIso = new Date().toISOString();

  // Determine initial alert level based on existing spend
  let initialAlert = 0;
  if (percentage >= 100) initialAlert = 100;
  else if (percentage >= 85) initialAlert = 85;

  const budgetPayload = {
    category: existing ? existing.category : categoryInput,
    monthlyLimit: monthlyLimit,
    currentSpent: currentSpent,
    remaining: remaining,
    lastAlertLevel: initialAlert,
    month: currentMonthStr,
    updatedAt: nowIso
  };

  let respMsg = `🎯 Budget Set: "${budgetPayload.category}" monthly limit is ₹${monthlyLimit.toLocaleString('en-IN')}.`;
  respMsg += `\nCurrent spend this month: ₹${currentSpent.toLocaleString('en-IN')} (${percentage}% used, ₹${remaining.toLocaleString('en-IN')} left).`;

  if (existing && existing.row_number) {
    return [{
      json: {
        operationType: 'update',
        sheetId,
        row_number: existing.row_number,
        response: respMsg,
        budget: budgetPayload,
        ...budgetPayload
      }
    }];
  } else {
    return [{
      json: {
        operationType: 'append',
        sheetId,
        response: respMsg,
        budget: budgetPayload,
        ...budgetPayload
      }
    }];
  }
}

// ACTION: CHECK / LIST / GET STATUS
if (action === 'check' || action === 'list' || action === 'get' || action === 'status') {
  if (budgetRows.length === 0) {
    return [{
      json: {
        operationType: 'read_only',
        success: true,
        status: 'EMPTY',
        response: "You haven't set any category budgets yet. You can set one anytime by saying: 'Set food budget to ₹10,000'!",
        budgets: []
      }
    }];
  }

  let totalBudget = 0;
  let totalSpentInBudgets = 0;
  let summaryStr = `📊 Monthly Budget Status (${currentMonthStr}):\n\n`;

  const enrichedBudgets = budgetRows.map(b => {
    const limit = parseFloat(b.monthlyLimit) || 0;
    const spent = categorySpendMap[b.category] || 0;
    const remaining = Math.max(0, limit - spent);
    const pct = limit > 0 ? Math.round((spent / limit) * 100) : 0;
    totalBudget += limit;
    totalSpentInBudgets += spent;

    let statusIcon = '🟢';
    if (pct >= 100) statusIcon = '🚨';
    else if (pct >= 85) statusIcon = '⚠️';

    summaryStr += `${statusIcon} **${b.category}**: ₹${spent.toLocaleString('en-IN')} / ₹${limit.toLocaleString('en-IN')} (${pct}%)\n`;
    summaryStr += `  • Remaining: ₹${remaining.toLocaleString('en-IN')}\n\n`;

    return {
      ...b,
      currentSpent: spent,
      remaining: remaining,
      percentage: pct
    };
  });

  const overallPct = totalBudget > 0 ? Math.round((totalSpentInBudgets / totalBudget) * 100) : 0;
  summaryStr += `**Total Budgeted**: ₹${totalSpentInBudgets.toLocaleString('en-IN')} / ₹${totalBudget.toLocaleString('en-IN')} (${overallPct}% used)`;

  return [{
    json: {
      operationType: 'read_only',
      success: true,
      status: 'SUCCESS',
      response: summaryStr.trim(),
      budgets: enrichedBudgets,
      totalBudget,
      totalSpentInBudgets
    }
  }];
}

// ACTION: EVALUATE_SPEND (Check threshold on new transaction)
if (action === 'evaluate_spend' || action === 'check_transaction') {
  const matched = findMatchingBudget(categoryInput);
  if (!matched) {
    return [{
      json: {
        operationType: 'read_only',
        success: true,
        hasBudget: false,
        alertTriggered: false,
        alertMessage: null
      }
    }];
  }

  const limit = parseFloat(matched.monthlyLimit) || 0;
  const spent = categorySpendMap[matched.category] || 0;
  const remaining = Math.max(0, limit - spent);
  const percentage = limit > 0 ? Math.round((spent / limit) * 100) : 0;
  const priorAlert = parseFloat(matched.lastAlertLevel) || 0;

  let alertTriggered = false;
  let newAlertLevel = priorAlert;
  let alertMsg = null;

  if (percentage >= 100 && priorAlert < 100) {
    alertTriggered = true;
    newAlertLevel = 100;
    alertMsg = `🚨 BUDGET EXCEEDED: You have reached 100% of your "${matched.category}" budget (₹${spent.toLocaleString('en-IN')} / ₹${limit.toLocaleString('en-IN')})! Any further spend will exceed your cap.`;
  } else if (percentage >= 85 && priorAlert < 85) {
    alertTriggered = true;
    newAlertLevel = 85;
    alertMsg = `⚠️ BUDGET ALERT: You have used ${percentage}% of your "${matched.category}" budget (₹${spent.toLocaleString('en-IN')} / ₹${limit.toLocaleString('en-IN')}). Only ₹${remaining.toLocaleString('en-IN')} remaining this month!`;
  }

  if (alertTriggered && matched.row_number) {
    // Persist new alert level so we do not spam repeated alerts
    const updateRow = {
      row_number: matched.row_number,
      category: matched.category,
      monthlyLimit: limit,
      currentSpent: spent,
      remaining: remaining,
      lastAlertLevel: newAlertLevel,
      month: currentMonthStr,
      updatedAt: new Date().toISOString()
    };
    return [{
      json: {
        operationType: 'update',
        sheetId,
        row_number: matched.row_number,
        alertTriggered: true,
        alertMessage: alertMsg,
        percentage: percentage,
        ...updateRow
      }
    }];
  }

  return [{
    json: {
      operationType: 'read_only',
      success: true,
      hasBudget: true,
      alertTriggered: false,
      alertMessage: null,
      percentage: percentage,
      spent: spent,
      limit: limit
    }
  }];
}

// ACTION: REMOVE / DELETE
if (action === 'delete' || action === 'remove') {
  const matched = findMatchingBudget(categoryInput);
  if (!matched) {
    return [{
      json: {
        operationType: 'read_only',
        success: false,
        status: 'NOT_FOUND',
        response: `⚠️ No active budget found for "${categoryInput}".`
      }
    }];
  }

  const clearRow = {
    row_number: matched.row_number,
    category: matched.category,
    monthlyLimit: 0,
    currentSpent: 0,
    remaining: 0,
    lastAlertLevel: 0,
    month: currentMonthStr,
    updatedAt: new Date().toISOString()
  };

  return [{
    json: {
      operationType: 'update',
      sheetId,
      row_number: matched.row_number,
      response: `Successfully removed budget for "${matched.category}".`,
      ...clearRow
    }
  }];
}

return [{
  json: {
    operationType: 'read_only',
    success: false,
    status: 'UNKNOWN_ACTION',
    response: `Unknown action "${action}". Supported actions: set, check, evaluate_spend, remove.`
  }
}];

const proc = $('Process Budget Request').first().json;
return {
  json: {
    success: true,
    status: 'CREATED',
    action: 'set',
    response: proc.response,
    budget: proc.budget
  }
};

const proc = $('Process Budget Request').first().json;
return {
  json: {
    success: true,
    status: 'UPDATED',
    action: proc.action || 'update',
    response: proc.response || (proc.alertMessage ? `⚠️ Alert: ${proc.alertMessage}` : 'Budget updated in sheet.'),
    alertTriggered: proc.alertTriggered || false,
    alertMessage: proc.alertMessage || null,
    percentage: proc.percentage || null,
    budget: proc.budget || null
  }
};

const proc = $input.first().json;
return {
  json: {
    success: proc.success !== undefined ? proc.success : true,
    status: proc.status || 'OK',
    action: proc.action || 'check',
    response: proc.response || 'Operation completed.',
    budgets: proc.budgets || [],
    alertTriggered: proc.alertTriggered || false,
    alertMessage: proc.alertMessage || null,
    error: proc.error || null
  }
};
